# ---- 2026-10-27 全量核验：只覆盖本轮点名的 5 张 ----
import 识字卡片_素材库 as lib


def _qa_fang():
    """放：球正在进入敞口收纳箱，动作终点明确。"""
    scene = lib.ground() + lib.box(515, top=330, w=184, h=108)
    child = lib.kid(270, 446, s=0.88, arms="point", point_at=(448, 326), look=(6, 2))
    ball = lib.ball(449, 334, 30, main=lib.RED, dark=lib.RED_D, hi=lib.PINK)
    motion = lib.P("M 426 286 Q 444 300 449 314", stroke=lib.TEAL, w=5)
    return scene + child + motion + ball


def _qa_lai():
    """来：妈妈从门口走向举手迎接的孩子。"""
    door = lib.wrap(
        lib.R(86, 202, 146, 220, 10, "#e9b97e"),
        lib.R(104, 220, 112, 202, 8, "#8a5a33"),
        lib.C(194, 322, 7, lib.YEL),
    )
    mother = lib.kid(350, 446, s=0.92, pose="stride", arms="swing", shirt=lib.RED,
                     bun=True, skirt=True, look=(5, 1))
    child = lib.kid(548, 438, s=0.58, arms="up", face="open", shirt=lib.TEAL)
    steps = lib.wrap(lib.E(270, 444, 12, 5, "#a5d0bd", 0.8),
                     lib.E(238, 450, 9, 4, "#a5d0bd", 0.55))
    return lib.ground() + door + steps + mother + child


def _qa_fei():
    """飞：披风孩子腾空，两臂均为正常长度的单段上举臂。"""
    clouds = lib.wrap(
        lib.cloud_p(130, 126, 0.72), lib.cloud_p(624, 104, 0.58),
        lib.cloud_p(624, 378, 0.78),
    )
    speed = lib.wrap(
        lib.L(82, 304, 220, 268, lib.TEAL_L, 8),
        lib.L(52, 358, 204, 324, lib.TEAL_L, 8),
        lib.L(138, 410, 252, 382, lib.TEAL_L, 7),
    )
    cape = lib.P("M 352 286 Q 274 274 238 328 Q 282 338 300 374 Q 326 350 354 378 Z", lib.RED)
    flyer = cape + lib.kid(400, 424, s=0.82, arms="up", face="open", shirt=lib.BLUE)
    return clouds + speed + f'<g transform="rotate(70 400 260)">{flyer}</g>'


def _qa_you():
    """游：与例句一致，画小鱼在水里游。"""
    water = lib.P("M 70 282 Q 125 258 180 282 T 290 282 T 400 282 T 510 282 T 620 282 "
                  "L 690 286 L 690 452 Q 380 470 70 452 Z", lib.WBLUE)
    fish = lib.wrap(
        lib.PG([(242, 356), (174, 310), (178, 402)], lib.RED),
        lib.E(356, 356, 128, 76, "#f2916c"),
        lib.E(382, 374, 88, 38, "#f7c5ae"),
        lib.PG([(334, 284), (386, 246), (410, 292)], lib.RED),
        lib.C(438, 334, 10, lib.INK), lib.C(441, 331, 3, lib.WHITE),
        lib.P("M 456 354 Q 474 374 452 390", stroke=lib.RED_D, w=6),
    )
    bubbles = lib.wrap(lib.C(510, 286, 10, lib.WHITE, 0.7),
                       lib.C(540, 246, 7, lib.WHITE, 0.65),
                       lib.C(558, 216, 5, lib.WHITE, 0.6))
    return water + fish + bubbles


def _qa_ju():
    """举：只举一只手，另一只自然下垂，贴合“举手答问题”。"""
    child = lib.kid(380, 446, s=1.05, arms="point", point_at=(458, 72),
                    face="open", look=(4, -3))
    rays = lib.wrap(lib.L(468, 112, 490, 88, lib.YEL, 6),
                    lib.L(486, 138, 516, 128, lib.YEL, 6))
    return lib.ground() + rays + child


_arts_before_qa = arts


def arts():
    result = dict(_arts_before_qa())
    result.update({"放": _qa_fang(), "来": _qa_lai(), "飞": _qa_fei(),
                   "游": _qa_you(), "举": _qa_ju()})
    return result


if __name__ == "__main__":
    import xml.etree.ElementTree as ET
    A = arts()
    for v in A.values():
        ET.fromstring(f'<g xmlns="http://www.w3.org/2000/svg">{{v}}</g>')
    print("自检通过 ✓", len(A), "卡")
